mapper.select:
SELECT  FROM review_feedback
WHERE owner_id=#{owner} AND session_id=#{sessionId} AND question_id=#{questionId} AND answer_id=#{answerId}
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

SELECT owner_id,feedback_id,revision,content_json,created_at FROM review_feedback_revision
WHERE owner_id=#{owner} AND feedback_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}

SELECT id,owner_id,feedback_id,feedback_revision,revision,choice,reason,created_at FROM review_feedback_decision
WHERE owner_id=#{owner} AND feedback_id=#{id} AND feedback_revision=#{feedbackRevision}
ORDER BY revision

SELECT a.id,a.revision,a.title,a.status,a.merged_into,
  (SELECT COUNT(*) FROM review_action_source s WHERE s.owner_id=a.owner_id AND s.action_id=a.id) AS source_count,
  (SELECT COUNT(*) FROM review_action_source s WHERE s.owner_id=a.owner_id AND s.action_id=a.id AND s.tracking='TRACKING') AS tracking_count,
  a.updated_at
FROM review_action a WHERE a.owner_id=#{owner}
AND a.status=#{status}
AND a.id > #{cursor}
ORDER BY a.id LIMIT #{limit}

SELECT owner_id,action_id,revision,change_kind AS `change`,snapshot_json,created_at FROM review_action_history
WHERE owner_id=#{owner} AND action_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}

mapper.update:
UPDATE review_action SET revision=#{action.revision},title=#{action.title},detail=#{action.detail},
  status=#{action.status},merged_into=#{action.mergedInto},updated_at=#{action.updatedAt}
WHERE owner_id=#{action.ownerId} AND id=#{action.id} AND revision=#{expected} AND status='OPEN'


UPDATE review_action_source SET verification=#{source.verification},tracking=#{source.tracking},
  tracking_reason=#{source.trackingReason},updated_at=#{source.updatedAt}
WHERE owner_id=#{source.ownerId} AND action_id=#{source.actionId} AND id=#{source.id}
